using System;using System.IO;using System.Web.Script.Serialization;using System.Device.Location;using System.Diagnostics;using System.Drawing;using System.Globalization;using System.Windows.Forms;
namespace AsterAlerts {
public sealed partial class AlertPanel {
 readonly Button locate=new Button{Text="Use my location",AutoSize=true,Dock=DockStyle.Fill};readonly Label locationStatus=new Label{Text="Choose Use my location, or enter coordinates above. The selected point stays fixed until you change it.",Dock=DockStyle.Fill,Font=new Font("Segoe UI",9)};GeoCoordinateWatcher watcher;readonly Timer locationTimer=new Timer{Interval=30000};
 internal void LoadHomeLocation(string path){if(!File.Exists(path))return;try{var values=new JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(path));double lat=Coordinate(Convert.ToString(values["latitude"],CultureInfo.InvariantCulture),-90,90),lon=Coordinate(Convert.ToString(values["longitude"],CultureInfo.InvariantCulture),-180,180);latitude.Text=lat.ToString("0.######",CultureInfo.InvariantCulture);longitude.Text=lon.ToString("0.######",CultureInfo.InvariantCulture);locationStatus.Text="Your home coordinates are selected from the local preset. Use my location only to replace them for this session.";}catch{locationStatus.Text="The home location preset could not be read. Enter coordinates or use Windows location.";}}
 public bool IsMonitoring {get{return worker!=null;}}
 void SetupLocation(TableLayoutPanel fields){fields.Controls.Add(locate,3,1);fields.Controls.Add(locationStatus,0,2);fields.SetColumnSpan(locationStatus,4);locate.BackColor=Color.FromArgb(32,49,72);locate.ForeColor=ForeColor;locate.FlatStyle=FlatStyle.Flat;locate.Click+=(s,e)=>BeginLocation();locationTimer.Tick+=(s,e)=>{CancelLocation();locationStatus.Text="No fresh location available. Enable Windows Location services or enter coordinates manually.";};}
 void BeginLocation(){if(IsMonitoring)return;CancelLocation();locate.Enabled=false;locationStatus.Text="Requesting your location from Windows… (up to 30 seconds)";try{var current=new GeoCoordinateWatcher(GeoPositionAccuracy.High);watcher=current;current.PositionChanged+=(s,e)=>Dispatch(()=>{if(watcher==current)ApplyLocation(e.Position,DateTimeOffset.UtcNow);});current.StatusChanged+=(s,e)=>Dispatch(()=>{if(watcher!=current)return;if(current.Permission==GeoPositionPermission.Denied||e.Status==GeoPositionStatus.Disabled){CancelLocation();locationStatus.Text="Location is blocked or unavailable. Check Windows Settings > Privacy & security > Location, or enter coordinates.";}else if(e.Status==GeoPositionStatus.NoData)locationStatus.Text="Windows has no location fix yet. Waiting up to 30 seconds…";});locationTimer.Start();current.Start(false);}catch{CancelLocation();locationStatus.Text="Windows location could not start. Enable a location provider or enter coordinates manually.";}}
 public static bool FreshPosition(GeoPosition<GeoCoordinate> position,DateTimeOffset now){if(position==null||position.Location==null||position.Location.IsUnknown)return false;var seconds=(now-position.Timestamp).TotalSeconds;return seconds>=-30&&seconds<=120;}
 internal bool ApplyLocation(GeoPosition<GeoCoordinate> position,DateTimeOffset now){if(!FreshPosition(position,now)){locationStatus.Text="Waiting for a fresh Windows location; an old or unknown fix was ignored.";return false;}var point=position.Location;latitude.Text=point.Latitude.ToString("F6",CultureInfo.InvariantCulture);longitude.Text=point.Longitude.ToString("F6",CultureInfo.InvariantCulture);string accuracy=double.IsNaN(point.HorizontalAccuracy)?"accuracy unavailable":"estimated accuracy ±"+point.HorizontalAccuracy.ToString("F0",CultureInfo.InvariantCulture)+" m";locationStatus.Text="Windows location selected · "+accuracy+". This is your current position; use it as home only when you are home.";CancelLocation();return true;}
 void CancelLocation(){locationTimer.Stop();var old=watcher;watcher=null;if(old!=null){old.Stop();old.Dispose();}if(!closing&&!IsDisposed)locate.Enabled=!IsMonitoring;}
 protected override void Dispose(bool disposing){if(disposing&&!closing){closing=true;CancelLocation();locationTimer.Dispose();StopWorker();token.Clear();chat.Clear();latitude.Clear();longitude.Clear();}base.Dispose(disposing);}
}
}
